-- 029 · Структура P&L в базе
-- ADR-0011, TASK-028.
--
-- Строки отчёта — порядок, подписи, уровень, раздел, вложенность и привязка
-- статей — это данные заведения и живут здесь. Формулы (итоги разделов,
-- маржа, доли food cost) остаются в src/lib/pnlCompute.js и находят строку по
-- key: расчётная строка в таблице есть, но её вид calc только говорит коду,
-- какую формулу применить.
--
-- Seed сгенерирован из PNL_STRUCTURE один в один; порядок массива стал
-- sort_order 10, 20, … — расчёт итогов (sum_children) зависит от порядка.
-- parent_key — вложенность группы для редактора; расчёт его не читает.
-- Совпадение проверено md5 по всем полям: a9e1963a6fd09d5de901b6a09532f9b0.
-- Повторный запуск ничего не задваивает.

CREATE TABLE IF NOT EXISTS public.pnl_lines (
  id SERIAL PRIMARY KEY,
  key TEXT UNIQUE NOT NULL,
  label TEXT NOT NULL,
  level INTEGER NOT NULL DEFAULT 0,
  section TEXT NOT NULL CHECK (section IN ('revenue','expenses','result','ratio')),
  source_kind TEXT CHECK (source_kind IN ('daily','bank','both')),
  category_code TEXT REFERENCES public.categories(code),
  daily_field TEXT,
  calc TEXT CHECK (calc IN ('sum_children','revenue_minus_opex','revenue_minus_all','ratio')),
  department TEXT REFERENCES public.departments(code),
  label_prefix TEXT,
  parent_key TEXT REFERENCES public.pnl_lines(key),
  sort_order INTEGER NOT NULL DEFAULT 0,
  is_active BOOLEAN NOT NULL DEFAULT true,
  created_at TIMESTAMPTZ DEFAULT now()
);

COMMENT ON TABLE public.pnl_lines IS
  'Строки P&L: порядок, подписи, вложенность и привязка статей. Формулы — в src/lib/pnlCompute.js по key (ADR-0011).';
COMMENT ON COLUMN public.pnl_lines.parent_key IS
  'Родительская группа строки (вложенность для редактора); расчёт итогов идёт по level и порядку.';

GRANT ALL ON public.pnl_lines TO anon;
GRANT USAGE, SELECT ON SEQUENCE pnl_lines_id_seq TO anon;
ALTER TABLE public.pnl_lines ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "All access pnl_lines" ON public.pnl_lines;
CREATE POLICY "All access pnl_lines" ON public.pnl_lines FOR ALL USING (true) WITH CHECK (true);

-- Родители ссылаются на строки той же таблицы: сначала все строки, затем parent_key.
