    AS x(key text, label text, level int, section text, source_kind text, category_code text, daily_field text,
         calc text, department text, label_prefix text, parent_key text, sort_order int)
  WHERE NOT EXISTS (SELECT 1 FROM public.pnl_lines)
), ins AS (
  INSERT INTO public.pnl_lines (key, label, level, section, source_kind, category_code, daily_field, calc, department, label_prefix, sort_order)
  SELECT key, label, level, section, source_kind, category_code, daily_field, calc, department, label_prefix, sort_order FROM src
  RETURNING key
)
UPDATE public.pnl_lines p SET parent_key = s.parent_key
FROM src s WHERE s.key = p.key AND s.parent_key IS NOT NULL AND p.key IN (SELECT key FROM ins);
